     1→use parking_lot::RwLock;
     2→use ssz_derive::{Decode, Encode};
     3→use std::marker::PhantomData;
     4→use std::sync::OnceLock;
     5→use std::{
     6→    collections::{BTreeMap, HashMap},
     7→    sync::atomic::{AtomicU64, Ordering},
     8→};
     9→use types::data_column_custody_group::{CustodyIndex, compute_columns_for_custody_group};
    10→use types::{ChainSpec, ColumnIndex, Epoch, EthSpec, Slot};
    11→
    12→/// A delay before making the CGC change effective to the data availability checker.
    13→const CUSTODY_CHANGE_DA_EFFECTIVE_DELAY_SECONDS: u64 = 30;
    14→
    15→/// Number of slots after which a validator's registration is removed if it has not re-registered.
    16→const VALIDATOR_REGISTRATION_EXPIRY_SLOTS: Slot = Slot::new(256);
    17→
    18→type ValidatorsAndBalances = Vec<(usize, u64)>;
    19→type SlotAndEffectiveBalance = (Slot, u64);
    20→
    21→/// This currently just registers increases in validator count.
    22→/// Does not handle decreasing validator counts
    23→#[derive(Default, Debug)]
    24→struct ValidatorRegistrations {
    25→    /// Set of all validators that is registered to this node along with its effective balance
    26→    ///
    27→    /// Key is validator index and value is effective_balance.
    28→    validators: HashMap<usize, SlotAndEffectiveBalance>,
    29→    /// Maintains the validator custody requirement at a given epoch.
    30→    ///
    31→    /// Note: Only stores the epoch value when there's a change in custody requirement.
    32→    /// So if epoch 10 and 11 has the same custody requirement, only 10 is stored.
    33→    /// This map is never pruned, because currently we never decrease custody requirement, so this
    34→    /// map size is contained at 128.
    35→    epoch_validator_custody_requirements: BTreeMap<Epoch, u64>,
    36→}
    37→
    38→impl ValidatorRegistrations {
    39→    /// Returns the validator custody requirement at the latest epoch.
    40→    fn latest_validator_custody_requirement(&self) -> Option<u64> {
    41→        self.epoch_validator_custody_requirements
    42→            .last_key_value()
    43→            .map(|(_, v)| *v)
    44→    }
    45→
    46→    /// Lookup the active custody requirement at the given epoch.
    47→    fn custody_requirement_at_epoch(&self, epoch: Epoch) -> Option<u64> {
    48→        self.epoch_validator_custody_requirements
    49→            .range(..=epoch)
    50→            .last()
    51→            .map(|(_, custody_count)| *custody_count)
    52→    }
    53→
    54→    /// Register a new validator index and updates the list of validators if required.
    55→    /// Returns `Some((effective_epoch, new_cgc))` if the registration results in a CGC update.
    56→    pub(crate) fn register_validators<E: EthSpec>(
    57→        &mut self,
    58→        validators_and_balance: ValidatorsAndBalances,
    59→        current_slot: Slot,
    60→        spec: &ChainSpec,
    61→    ) -> Option<(Epoch, u64)> {
    62→        for (validator_index, effective_balance) in validators_and_balance {
    63→            self.validators
    64→                .insert(validator_index, (current_slot, effective_balance));
    65→        }
    66→
    67→        // Drop validators that haven't re-registered with the node for `VALIDATOR_REGISTRATION_EXPIRY_SLOTS`.
    68→        self.validators
    69→            .retain(|_, (slot, _)| *slot >= current_slot - VALIDATOR_REGISTRATION_EXPIRY_SLOTS);
    70→
    71→        // Each `BALANCE_PER_ADDITIONAL_CUSTODY_GROUP` effectively contributes one unit of "weight".
    72→        let validator_custody_units = self.validators.values().map(|(_, eb)| eb).sum::<u64>()
    73→            / spec.balance_per_additional_custody_group;
    74→        let validator_custody_requirement =
    75→            get_validators_custody_requirement(validator_custody_units, spec);
    76→
    77→        tracing::debug!(
    78→            validator_custody_units,
    79→            validator_custody_requirement,
    80→            "Registered validators"
    81→        );
    82→
    83→        // If registering the new validator increased the total validator "units", then
    84→        // add a new entry for the current epoch
    85→        if Some(validator_custody_requirement) > self.latest_validator_custody_requirement() {
    86→            // Apply the change from the next epoch after adding some delay buffer to ensure
    87→            // the node has enough time to subscribe to subnets etc, and to avoid having
    88→            // inconsistent column counts within an epoch.
    89→            let effective_delay_slots =
    90→                CUSTODY_CHANGE_DA_EFFECTIVE_DELAY_SECONDS / spec.seconds_per_slot;
    91→            let effective_epoch =
    92→                (current_slot + effective_delay_slots).epoch(E::slots_per_epoch()) + 1;
    93→            self.epoch_validator_custody_requirements
    94→                .entry(effective_epoch)
    95→                .and_modify(|old_custody| *old_custody = validator_custody_requirement)
    96→                .or_insert(validator_custody_requirement);
    97→            Some((effective_epoch, validator_custody_requirement))
    98→        } else {
    99→            None
   100→        }
   101→    }
   102→}
   103→
   104→/// Given the `validator_custody_units`, return the custody requirement based on
   105→/// the spec parameters.
   106→///
   107→/// Note: a `validator_custody_units` here represents the number of 32 eth effective_balance
   108→/// equivalent to `BALANCE_PER_ADDITIONAL_CUSTODY_GROUP`.
   109→///
   110→/// For e.g. a validator with eb 32 eth is 1 unit.
   111→/// a validator with eb 65 eth is 65 // 32 = 2 units.
   112→///
   113→/// See https://github.com/ethereum/consensus-specs/blob/dev/specs/fulu/validator.md#validator-custody
   114→fn get_validators_custody_requirement(validator_custody_units: u64, spec: &ChainSpec) -> u64 {
   115→    std::cmp::min(
   116→        std::cmp::max(validator_custody_units, spec.validator_custody_requirement),
   117→        spec.number_of_custody_groups,
   118→    )
   119→}
