   121→/// Contains all the information the node requires to calculate the
   122→/// number of columns to be custodied when checking for DA.
   123→#[derive(Debug)]
   124→pub struct CustodyContext<E: EthSpec> {
   125→    /// The Number of custody groups required based on the number of validators
   126→    /// that is attached to this node.
   127→    ///
   128→    /// This is the number that we use to compute the custody group count that
   129→    /// we require for data availability check, and we use to advertise to our peers in the metadata
   130→    /// and enr values.
   131→    validator_custody_count: AtomicU64,
   132→    /// Is the node run as a supernode based on current cli parameters.
   133→    pub current_is_supernode: bool,
   134→    /// The persisted value for `is_supernode` based on the previous run of this node.
   135→    ///
   136→    /// Note: We require this value because if a user restarts the node with a higher cli custody
   137→    /// count value than in the previous run, then we should continue advertising the custody
   138→    /// count based on the old value than the new one since we haven't backfilled the required
   139→    /// columns.
   140→    persisted_is_supernode: bool,
   141→    /// Maintains all the validators that this node is connected to currently
   142→    validator_registrations: RwLock<ValidatorRegistrations>,
   143→    /// Stores an immutable, ordered list of all custody columns as determined by the node's NodeID
   144→    /// on startup.
   145→    all_custody_columns_ordered: OnceLock<Box<[ColumnIndex]>>,
   146→    _phantom_data: PhantomData<E>,
   147→}
   148→
   149→impl<E: EthSpec> CustodyContext<E> {
   150→    /// Create a new custody default custody context object when no persisted object
   151→    /// exists.
   152→    ///
   153→    /// The `is_supernode` value is based on current cli parameters.
   154→    pub fn new(is_supernode: bool) -> Self {
   155→        Self {
   156→            validator_custody_count: AtomicU64::new(0),
   157→            current_is_supernode: is_supernode,
   158→            persisted_is_supernode: is_supernode,
   159→            validator_registrations: Default::default(),
   160→            all_custody_columns_ordered: OnceLock::new(),
   161→            _phantom_data: PhantomData,
   162→        }
   163→    }
   164→
   165→    pub fn new_from_persisted_custody_context(
   166→        ssz_context: CustodyContextSsz,
   167→        is_supernode: bool,
   168→    ) -> Self {
   169→        CustodyContext {
   170→            validator_custody_count: AtomicU64::new(ssz_context.validator_custody_at_head),
   171→            current_is_supernode: is_supernode,
   172→            persisted_is_supernode: ssz_context.persisted_is_supernode,
   173→            validator_registrations: RwLock::new(ValidatorRegistrations {
   174→                validators: Default::default(),
   175→                epoch_validator_custody_requirements: ssz_context
   176→                    .epoch_validator_custody_requirements
   177→                    .into_iter()
   178→                    .collect(),
   179→            }),
   180→            all_custody_columns_ordered: OnceLock::new(),
   181→            _phantom_data: PhantomData,
   182→        }
   183→    }
   184→
   185→    /// Initializes an ordered list of data columns based on provided custody groups.
   186→    ///
   187→    /// # Arguments
   188→    /// * `all_custody_groups_ordered` - Vector of custody group indices to map to columns
   189→    /// * `spec` - Chain specification containing custody parameters
   190→    ///
   191→    /// # Returns
   192→    /// Ok(()) if initialization succeeds, Err with description string if it fails
   193→    pub fn init_ordered_data_columns_from_custody_groups(
   194→        &self,
   195→        all_custody_groups_ordered: Vec<CustodyIndex>,
   196→        spec: &ChainSpec,
   197→    ) -> Result<(), String> {
   198→        let mut ordered_custody_columns = vec![];
   199→        for custody_index in all_custody_groups_ordered {
   200→            let columns = compute_columns_for_custody_group::<E>(custody_index, spec)
   201→                .map_err(|e| format!("Failed to compute columns for custody group {e:?}"))?;
   202→            ordered_custody_columns.extend(columns);
   203→        }
   204→        self.all_custody_columns_ordered
   205→            .set(ordered_custody_columns.into_boxed_slice())
   206→            .map_err(|_| {
   207→                "Failed to initialise CustodyContext with computed custody columns".to_string()
   208→            })
   209→    }
   210→
   211→    /// Register a new validator index and updates the list of validators if required.
   212→    ///
   213→    /// Also modifies the internal structures if the validator custody has changed to
   214→    /// update the `custody_column_count`.
   215→    ///
   216→    /// Returns `Some` along with the updated custody group count if it has changed, otherwise returns `None`.
   217→    pub fn register_validators(
   218→        &self,
   219→        validators_and_balance: ValidatorsAndBalances,
   220→        current_slot: Slot,
   221→        spec: &ChainSpec,
   222→    ) -> Option<CustodyCountChanged> {
   223→        let Some((effective_epoch, new_validator_custody)) = self
   224→            .validator_registrations
   225→            .write()
   226→            .register_validators::<E>(validators_and_balance, current_slot, spec)
   227→        else {
   228→            return None;
   229→        };
   230→
   231→        let current_cgc = self.custody_group_count_at_head(spec);
   232→        let validator_custody_count_at_head = self.validator_custody_count.load(Ordering::Relaxed);
   233→
   234→        if new_validator_custody != validator_custody_count_at_head {
   235→            tracing::debug!(
   236→                old_count = validator_custody_count_at_head,
   237→                new_count = new_validator_custody,
   238→                "Validator count at head updated"
   239→            );
   240→            self.validator_custody_count
   241→                .store(new_validator_custody, Ordering::Relaxed);
   242→
   243→            let updated_cgc = self.custody_group_count_at_head(spec);
   244→            // Send the message to network only if there are more columns subnets to subscribe to
   245→            if updated_cgc > current_cgc {
   246→                tracing::debug!(
   247→                    old_cgc = current_cgc,
   248→                    updated_cgc,
   249→                    "Custody group count updated"
   250→                );
   251→                return Some(CustodyCountChanged {
   252→                    new_custody_group_count: updated_cgc,
   253→                    sampling_count: self.num_of_custody_groups_to_sample(effective_epoch, spec),
   254→                    effective_epoch,
   255→                });
   256→            }
   257→        }
   258→
   259→        None
   260→    }
   261→
   262→    /// This function is used to determine the custody group count at head ONLY.
   263→    /// Do NOT use this directly for data availability check, use `self.sampling_size` instead as
   264→    /// CGC can change over epochs.
   265→    pub fn custody_group_count_at_head(&self, spec: &ChainSpec) -> u64 {
   266→        if self.current_is_supernode {
   267→            return spec.number_of_custody_groups;
   268→        }
   269→        let validator_custody_count_at_head = self.validator_custody_count.load(Ordering::Relaxed);
   270→
   271→        // If there are no validators, return the minimum custody_requirement
   272→        if validator_custody_count_at_head > 0 {
   273→            validator_custody_count_at_head
   274→        } else {
   275→            spec.custody_requirement
   276→        }
   277→    }
   278→
   279→    /// This function is used to determine the custody group count at a given epoch.
   280→    ///
   281→    /// This differs from the number of custody groups sampled per slot, as the spec requires a
   282→    /// minimum sampling size which may exceed the custody group count (CGC).
   283→    ///
   284→    /// See also: [`Self::num_of_custody_groups_to_sample`].
   285→    fn custody_group_count_at_epoch(&self, epoch: Epoch, spec: &ChainSpec) -> u64 {
   286→        if self.current_is_supernode {
   287→            spec.number_of_custody_groups
   288→        } else {
   289→            self.validator_registrations
   290→                .read()
   291→                .custody_requirement_at_epoch(epoch)
   292→                .unwrap_or(spec.custody_requirement)
   293→        }
   294→    }
   295→
   296→    /// Returns the count of custody groups this node must _sample_ for a block at `epoch` to import.
   297→    pub fn num_of_custody_groups_to_sample(&self, epoch: Epoch, spec: &ChainSpec) -> u64 {
   298→        let custody_group_count = self.custody_group_count_at_epoch(epoch, spec);
   299→        spec.sampling_size_custody_groups(custody_group_count)
   300→            .expect("should compute node sampling size from valid chain spec")
   301→    }
   302→
   303→    /// Returns the count of columns this node must _sample_ for a block at `epoch` to import.
   304→    pub fn num_of_data_columns_to_sample(&self, epoch: Epoch, spec: &ChainSpec) -> usize {
   305→        let custody_group_count = self.custody_group_count_at_epoch(epoch, spec);
   306→        spec.sampling_size_columns::<E>(custody_group_count)
   307→            .expect("should compute node sampling size from valid chain spec")
   308→    }
   309→
   310→    /// Returns the ordered list of column indices that should be sampled for data availability checking at the given epoch.
   311→    ///
   312→    /// # Parameters
   313→    /// * `epoch` - Epoch to determine sampling columns for
   314→    /// * `spec` - Chain specification containing sampling parameters
   315→    ///
   316→    /// # Returns
   317→    /// A slice of ordered column indices that should be sampled for this epoch based on the node's custody configuration
   318→    pub fn sampling_columns_for_epoch(&self, epoch: Epoch, spec: &ChainSpec) -> &[ColumnIndex] {
   319→        let num_of_columns_to_sample = self.num_of_data_columns_to_sample(epoch, spec);
   320→        let all_columns_ordered = self
   321→            .all_custody_columns_ordered
   322→            .get()
   323→            .expect("all_custody_columns_ordered should be initialized");
   324→        &all_columns_ordered[..num_of_columns_to_sample]
   325→    }
   326→
   327→    /// Returns the ordered list of column indices that the node is assigned to custody
   328→    /// (and advertised to peers) at the given epoch. If epoch is `None`, this function
   329→    /// computes the custody columns at head.
   330→    ///
   331→    /// This method differs from [`self::sampling_columns_for_epoch`] which returns all sampling columns.
   332→    /// The columns returned by this method are either identical to or a subset of the sampling columns,
   333→    /// representing only those columns that this node is responsible for maintaining custody of.
   334→    ///
   335→    /// # Parameters
   336→    /// * `epoch_opt` - Optional epoch to determine custody columns for.
   337→    ///
   338→    /// # Returns
   339→    /// A slice of ordered custody column indices for this epoch based on the node's custody configuration
   340→    pub fn custody_columns_for_epoch(
   341→        &self,
   342→        epoch_opt: Option<Epoch>,
   343→        spec: &ChainSpec,
   344→    ) -> &[ColumnIndex] {
   345→        let custody_group_count = if let Some(epoch) = epoch_opt {
   346→            self.custody_group_count_at_epoch(epoch, spec) as usize
   347→        } else {
   348→            self.custody_group_count_at_head(spec) as usize
   349→        };
   350→
   351→        let all_columns_ordered = self
   352→            .all_custody_columns_ordered
   353→            .get()
   354→            .expect("all_custody_columns_ordered should be initialized");
   355→        &all_columns_ordered[..custody_group_count]
   356→    }
   357→}
   358→
   359→/// The custody count changed because of a change in the
   360→/// number of validators being managed.
   361→pub struct CustodyCountChanged {
   362→    pub new_custody_group_count: u64,
   363→    pub sampling_count: u64,
   364→    pub effective_epoch: Epoch,
   365→}
   366→
   367→/// The custody information that gets persisted across runs.
   368→#[derive(Debug, Encode, Decode, Clone)]
   369→pub struct CustodyContextSsz {
   370→    pub validator_custody_at_head: u64,
   371→    pub persisted_is_supernode: bool,
   372→    pub epoch_validator_custody_requirements: Vec<(Epoch, u64)>,
   373→}
   374→
   375→impl<E: EthSpec> From<&CustodyContext<E>> for CustodyContextSsz {
   376→    fn from(context: &CustodyContext<E>) -> Self {
   377→        CustodyContextSsz {
   378→            validator_custody_at_head: context.validator_custody_count.load(Ordering::Relaxed),
   379→            persisted_is_supernode: context.persisted_is_supernode,
   380→            epoch_validator_custody_requirements: context
   381→                .validator_registrations
   382→                .read()
   383→                .epoch_validator_custody_requirements
   384→                .iter()
   385→                .map(|(epoch, count)| (*epoch, *count))
   386→                .collect(),
   387→        }
   388→    }
   389→}
