   391→#[cfg(test)]
   392→mod tests {
   393→    use rand::rng;
   394→    use rand::seq::SliceRandom;
   395→    use types::MainnetEthSpec;
   396→
   397→    use super::*;
   398→
   399→    type E = MainnetEthSpec;
   400→
   401→    #[test]
   402→    fn no_validators_supernode_default() {
   403→        let custody_context = CustodyContext::<E>::new(true);
   404→        let spec = E::default_spec();
   405→        assert_eq!(
   406→            custody_context.custody_group_count_at_head(&spec),
   407→            spec.number_of_custody_groups
   408→        );
   409→        assert_eq!(
   410→            custody_context.num_of_custody_groups_to_sample(Epoch::new(0), &spec),
   411→            spec.number_of_custody_groups
   412→        );
   413→    }
   414→
   415→    #[test]
   416→    fn no_validators_fullnode_default() {
   417→        let custody_context = CustodyContext::<E>::new(false);
   418→        let spec = E::default_spec();
   419→        assert_eq!(
   420→            custody_context.custody_group_count_at_head(&spec),
   421→            spec.custody_requirement,
   422→            "head custody count should be minimum spec custody requirement"
   423→        );
   424→        assert_eq!(
   425→            custody_context.num_of_custody_groups_to_sample(Epoch::new(0), &spec),
   426→            spec.samples_per_slot
   427→        );
   428→    }
   429→
   430→    #[test]
   431→    fn register_single_validator_should_update_cgc() {
   432→        let custody_context = CustodyContext::<E>::new(false);
   433→        let spec = E::default_spec();
   434→        let bal_per_additional_group = spec.balance_per_additional_custody_group;
   435→        let min_val_custody_requirement = spec.validator_custody_requirement;
   436→        // One single node increases its balance over 3 epochs.
   437→        let validators_and_expected_cgc_change = vec![
   438→            (
   439→                vec![(0, bal_per_additional_group)],
   440→                Some(min_val_custody_requirement),
   441→            ),
   442→            // No CGC change at 8 custody units, as it's the minimum requirement
   443→            (vec![(0, 8 * bal_per_additional_group)], None),
   444→            (vec![(0, 10 * bal_per_additional_group)], Some(10)),
   445→        ];
   446→
   447→        register_validators_and_assert_cgc::<E>(
   448→            &custody_context,
   449→            validators_and_expected_cgc_change,
   450→            &spec,
   451→        );
   452→    }
   453→
   454→    #[test]
   455→    fn register_multiple_validators_should_update_cgc() {
   456→        let custody_context = CustodyContext::<E>::new(false);
   457→        let spec = E::default_spec();
   458→        let bal_per_additional_group = spec.balance_per_additional_custody_group;
   459→        let min_val_custody_requirement = spec.validator_custody_requirement;
   460→        // Add 3 validators over 3 epochs.
   461→        let validators_and_expected_cgc = vec![
   462→            (
   463→                vec![(0, bal_per_additional_group)],
   464→                Some(min_val_custody_requirement),
   465→            ),
   466→            (
   467→                vec![
   468→                    (0, bal_per_additional_group),
   469→                    (1, 7 * bal_per_additional_group),
   470→                ],
   471→                // No CGC change at 8 custody units, as it's the minimum requirement
   472→                None,
   473→            ),
   474→            (
   475→                vec![
   476→                    (0, bal_per_additional_group),
   477→                    (1, 7 * bal_per_additional_group),
   478→                    (2, 2 * bal_per_additional_group),
   479→                ],
   480→                Some(10),
   481→            ),
